  padding: 12px;
}
.card h3 { margin: 0 0 10px; font-size: 15px; color: #c5cee8; }
.row { display: flex; gap: 10px; align-items: center; }
.space { justify-content: space-between; }
.badge { padding: 2px 8px; border-radius: 999px; font-size: 12px; }
.good { color: var(--good); }
.bad { color: var(--bad); }
.badge.good { background: rgba(46,204,113,.15); color: var(--good); }
.badge.bad { background: rgba(255,91,110,.16); color: var(--bad); }
.table { width: 100%; border-collapse: collapse; font-size: 13px; }
.table th, .table td { padding: 8px 6px; border-bottom: 1px solid #262c46; text-align: left; }
.table th { color: var(--muted); font-weight: 500; font-size: 12px; text-transform: uppercase; }
.kpi { font-size: 26px; font-weight: 700; }
.mini { color: var(--muted); font-size: 12px; }
.spark {
  height: 28px;
  width: 80px;
  border-radius: 4px;
  background: linear-gradient(180deg, rgba(25,182,255,.35), rgba(25,182,255,.05));
  position: relative;
  overflow: hidden;
}
.spark::after {
  content: "";
  position: absolute;
  inset: 8px 6px;
  border-top: 2px solid #6ed3ff;
  border-right: 2px solid transparent;
  transform: skewX(-25deg);
}
.tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 10px; }
.tab-btn {
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--muted);
  padding: 6px 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 12px;
}
.tab-btn.active { color: #fff; border-color: #3b8ab5; background: #1b3140; }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.marketbar { display: grid; grid-template-columns: repeat(6,1fr); gap: 8px; }
.market-pill {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px;
  min-width: 0;
}
.market-pill .name { color: var(--muted); font-size: 12px; }
.market-pill .value { font-weight: 700; font-size: 15px; }
.market-pill .chg { font-size: 12px; }
.layout-home { display: grid; grid-template-columns: 2fr 1fr; gap: 12px; margin-top: 12px; }
.layout-chart { display: grid; grid-template-columns: 280px 1fr 340px; gap: 10px; }
.watch-group button {
  width: 100%; text-align: left; background: #14182a; color: #c4ceea;
  border: 1px solid var(--border); border-radius: 8px; padding: 8px; margin-top: 8px;
}
.watch-items { display: none; margin-top: 6px; }
.watch-items.open { display: block; }
.toolbar { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 8px; }
.toolbar .tab-btn { padding: 5px 9px; }
.chart-area {
  height: 460px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background:
    repeating-linear-gradient(to right, rgba(255,255,255,.03) 0, rgba(255,255,255,.03) 1px, transparent 1px, transparent 48px),
    repeating-linear-gradient(to bottom, rgba(255,255,255,.03) 0, rgba(255,255,255,.03) 1px, transparent 1px, transparent 44px),
    #111528;
  position: relative;
  overflow: hidden;
}
.candle { position: absolute; bottom: 60px; width: 8px; background: var(--good); }
.candle.red { background: var(--bad); }
.footer-note { color: var(--muted); font-size: 12px; margin-top: 14px; }
.broker-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; }
.broker-card .tier { font-size: 12px; color: #eacb7a; }
.community-post { border-top: 1px solid #28304b; padding-top: 10px; margin-top: 10px; }
@media (max-width: 1100px) {
  .layout-chart { grid-template-columns: 1fr; }
  .layout-home { grid-template-columns: 1fr; }
  .broker-grid { grid-template-columns: 1fr; }
  .marketbar { grid-template-columns: repeat(2,1fr); }
}
